def mergeKLists(self, lists: list[ListNode]) -> ListNode:
    if not lists:
        return None
    return self._merge(lists, 0, len(lists) - 1)

def _merge(self, lists, lo, hi):
    if lo == hi:
        return lists[lo]
    mid = (lo + hi) // 2
    left = self._merge(lists, lo, mid)
    right = self._merge(lists, mid + 1, hi)
    return self._merge_two(left, right)

def _merge_two(self, a, b):
    dummy = ListNode(0)
    curr = dummy
    while a and b:
        if a.val <= b.val:
            curr.next = a
            a = a.next
        else:
            curr.next = b
            b = b.next
        curr = curr.next
    curr.next = a if a else b
    return dummy.next

